B.a1l=new A.c3("\u062d\u064e\u0642\u0651\u064f \u0627\u0644\u0652\u0648\u064e\u0644\u064e\u062f\u0650 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0648\u064e\u0627\u0644\u0650\u062f\u0650 \u0623\u064e\u0646\u0652 \u064a\u064f\u062d\u0652\u0633\u0650\u0646\u064e \u0671\u0633\u0652\u0645\u064e\u0647\u064f\u060c \u0648\u064e\u064a\u064f\u062d\u0652\u0633\u0650\u0646\u064e \u0623\u064e\u062f\u064e\u0628\u064e\u0647\u064f\u060c \u0648\u064e\u064a\u064f\u0639\u064e\u0644\u0651\u0650\u0645\u064e\u0647\u064f \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u064e","\u0627\u0644\u0625\u0645\u0627\u0645 \u0639\u0644\u064a (\u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645)","\u0645\u064a\u0632\u0627\u0646 \u0627\u0644\u062d\u0643\u0645\u0629\u060c \u062c \u0663\u060c \u0635 \u0662\u0665\u0662\u0662")
B.a1s=new A.c3("\u0627\u062c\u0652\u0639\u064e\u0644\u064f\u0648\u0627 \u0644\u0650\u0628\u064f\u064a\u064f\u0648\u062a\u0650\u0643\u064f\u0645\u0652 \u0646\u064e\u0635\u0650\u064a\u0628\u064b\u0627 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u0650\u060c \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u0628\u064e\u064a\u0652\u062a\u064e \u0625\u0650\u0630\u064e\u0627 \u0642\u064f\u0631\u0650\u0623\u064e \u0641\u0650\u064a\u0647\u0650 \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u064f \u064a\u064f\u0633\u0651\u0650\u0631\u064e \u0639\u064e\u0644\u064e\u0649 \u0623\u064e\u0647\u0652\u0644\u0650\u0647\u0650\u060c \u0648\u064e\u0643\u064e\u062b\u064f\u0631\u064e \u062e\u064e\u064a\u0652\u0631\u064f\u0647\u064f\u060c \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0633\u064f\u0643\u0651\u064e\u0627\u0646\u064f\u0647\u064f \u0641\u0650\u064a \u0632\u0650\u064a\u064e\u0627\u062f\u064e\u0629\u064d\u060c \u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0644\u064e\u0645\u0652 \u064a\u064f\u0642\u0652\u0631\u064e\u0623\u0652 \u0641\u0650\u064a\u0647\u0650 \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u064f \u0636\u064f\u064a\u0651\u0650\u0642\u064e \u0639\u064e\u0644\u064e\u0649 \u0623\u064e\u0647\u064e\u0644\u0650\u0647\u0650\u060c \u0648\u064e\u0642\u064e\u0644\u0651\u064e \u062e\u064e\u064a\u0652\u0631\u064f\u0647\u064f\u060c \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0633\u064f\u0643\u0651\u064e\u0627\u0646\u064f\u0647\u064f \u0641\u0650\u064a \u0646\u064f\u0642\u0652\u0635\u064e\u0627\u0646\u064d","\u0627\u0644\u0646\u0628\u064a \u0627\u0644\u0623\u0639\u0638\u0645 (\u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0622\u0644\u0647 \u0648\u0633\u0644\u0645)","\u0648\u0633\u0627\u0626\u0644 \u0627\u0644\u0634\u064a\u0639\u0629\u060c \u062c \u0666\u060c \u0635 \u0662\u0660\u0660")
B.a1g=new A.c3("\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u0628\u064e\u064a\u0652\u062a\u064e \u0625\u0650\u0630\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0641\u0650\u064a\u0647\u0650 \u0627\u0644\u0652\u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064f \u064a\u064e\u062a\u0652\u0644\u064f\u0648 \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u064e\u060c \u064a\u064e\u062a\u064e\u0631\u064e\u0627\u0621\u064e\u0627\u0647\u064f \u0623\u064e\u0647\u0652\u0644\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0643\u064e\u0645\u064e\u0627 \u064a\u064e\u062a\u064e\u0631\u064e\u0627\u0621\u064e\u0649 \u0623\u064e\u0647\u0652\u0644\u064f \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0627\u0644\u0643\u064e\u0648\u0652\u0643\u064e\u0628\u064e \u0627\u0644\u062f\u0651\u064f\u0631\u0651\u0650\u064a\u0651\u064e \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650","\u0627\u0644\u0625\u0645\u0627\u0645 \u062c\u0639\u0641\u0631 \u0627\u0644\u0635\u0627\u062f\u0642 (\u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645)","\u0628\u062d\u0627\u0631 \u0627\u0644\u0623\u0646\u0648\u0627\u0631\u060c \u062c \u0668\u0669\u060c \u0635 \u0662\u0660\u0660")
B.a1n=new A.c3("\u0625\u0650\u0646\u0651\u064e \u0647\u064e\u0630\u0650\u0647\u0650 \u0627\u0644\u0652\u0642\u064f\u0644\u064f\u0648\u0628\u064e \u062a\u064e\u0635\u0652\u062f\u064e\u0623\u064f \u0643\u064e\u0645\u064e\u0627 \u064a\u064e\u0635\u0652\u062f\u064e\u0623\u064f \u0627\u0644\u0652\u062d\u064e\u062f\u0650\u064a\u062f\u064f \u0625\u0650\u0630\u064e\u0627 \u0623\u064e\u0635\u064e\u0627\u0628\u064e\u0647\u064f \u0627\u0644\u0652\u0645\u064e\u0627\u0621\u064f\u060c \u0642\u0650\u064a\u0644\u064e: \u0648\u064e\u0645\u064e\u0627 \u062c\u064e\u0644\u064e\u0627\u0624\u064f\u0647\u064e\u0627\u061f \u0642\u064e\u0627\u0644\u064e: \u0643\u064e\u062b\u0652\u0631\u064e\u0629\u064f \u0630\u0650\u0643\u0652\u0631\u0650 \u0627\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u0650\u060c \u0648\u064e\u062a\u0650\u0644\u064e\u0627\u0648\u064e\u0629 \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u0650","\u0627\u0644\u0646\u0628\u064a \u0627\u0644\u0623\u0639\u0638\u0645 (\u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0622\u0644\u0647 \u0648\u0633\u0644\u0645)","\u0645\u064a\u0632\u0627\u0646 \u0627\u0644\u062d\u0643\u0645\u0629\u060c \u062c \u0663\u060c \u0635 \u0662\u0666\u0661\u0666")
B.a1N=new A.c3("\u0646\u064e\u0648\u0651\u0650\u0631\u064f\u0648\u0627 \u0628\u064f\u064a\u064f\u0648\u062a\u064e\u0643\u064f\u0645\u0652 \u0628\u0650\u062a\u0650\u0644\u064e\u0627\u0648\u064e\u0629\u0650 \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u0650 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0647\u064e\u0627 \u0642\u064f\u0628\u064f\u0648\u0631\u064b\u0627 \u0643\u064e\u0645\u064e\u0627 \u0641\u064e\u0639\u064e\u0644\u064e\u062a\u0650 \u0627\u0644\u0652\u064a\u064e\u0647\u064f\u0648\u062f\u064f \u0648\u064e\u0627\u0644\u0646\u0651\u064e\u0635\u064e\u0627\u0631\u064e\u0649\u060c \u0635\u064e\u0644\u0651\u064e\u0648\u0652\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0643\u064e\u0646\u064e\u0627\u0626\u0650\u0633\u064e \u0648\u064e\u0627\u0644\u0652\u0628\u0650\u064a\u064e\u0639\u0650 \u0648\u064e\u0639\u064e\u0637\u0651\u064e\u0644\u064f\u0648\u0627 \u0628\u064f\u064a\u064f\u0648\u062a\u064e\u0647\u064f\u0645\u0652\u060c \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u0628\u064e\u064a\u0652\u062a\u064e \u0625\u0650\u0630\u064e\u0627 \u0643\u064e\u062b\u064f\u0631\u064e \u0641\u0650\u064a\u0647\u0650 \u062a\u0650\u0644\u064e\u0627\u0648\u064e\u0629\u064f \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u0650 \u0643\u064e\u062b\u064f\u0631\u064e \u062e\u064e\u064a\u0652\u0631\u064f\u0647\u064f \u0648\u064e\u0627\u062a\u0651\u064e\u0633\u064e\u0639\u064e \u0623\u064e\u0647\u0652\u0644\u064f\u0647\u064f\u060c \u0648\u064e\u0623\u064e\u0636\u064e\u0627\u0621\u064e \u0644\u0650\u0623\u064e\u0647\u0652\u0644\u0650 \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0643\u064e\u0645\u064e\u0627 \u062a\u064f\u0636\u0650\u0626\u064f \u0646\u064f\u062c\u064f\u0648\u0645\u064f \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0621\u0650 \u0644\u0650\u0623\u064e\u0647\u0652\u0644\u0650 \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627","\u0627\u0644\u0646\u0628\u064a \u0627\u0644\u0623\u0639\u0638\u0645 (\u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0622\u0644\u0647 \u0648\u0633\u0644\u0645)","\u0648\u0633\u0627\u0626\u0644 \u0627\u0644\u0634\u064a\u0639\u0629\u060c \u062c \u0666\u060c \u0635 \u0662\u0660\u0660")
B.a1k=new A.c3("\u0648\u064e\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u064e \u0638\u064e\u0627\u0647\u0650\u0631\u064f\u0647\u064f \u0623\u064e\u0646\u0650\u064a\u0642\u064c \u0648\u064e\u0628\u064e\u0627\u0637\u0650\u0646\u064f\u0647\u064f \u0639\u064e\u0645\u0650\u064a\u0642\u064c\u060c \u0644\u064e\u0627 \u062a\u064e\u0641\u0652\u0646\u064e\u0649 \u0639\u064e\u062c\u064e\u0627\u0626\u0650\u0628\u064f\u0647\u064f\u060c \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0646\u0652\u0642\u064e\u0636\u0650\u064a \u063a\u064e\u0631\u064e\u0627\u0626\u0650\u0628\u064f\u0647\u064f\u060c \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0643\u0652\u0634\u064e\u0641\u064f \u0627\u0644\u0638\u0651\u064f\u0644\u064f\u0645\u064e\u0627\u062a\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0647\u0650","\u0627\u0644\u0625\u0645\u0627\u0645 \u0639\u0644\u064a (\u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645)","\u0645\u0633\u062a\u062f\u0631\u0643 \u0633\u0641\u064a\u0646\u0629 \u0627\u0644\u0628\u062d\u0627\u0631\u060c \u062c \u0663\u060c \u0635 \u0661\u0660\u0662")
B.a1y=new A.c3("\u0639\u064e\u0646\u0652 \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645\u064e \u0628\u0652\u0646\u0650 \u0627\u0644\u0652\u0639\u064e\u0628\u0651\u064e\u0627\u0633\u0650 \u0642\u064e\u0627\u0644\u064e: \u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0631\u0651\u0650\u0636\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0627\u0644\u0633\u0651\u064e\u0644\u064e\u0627\u0645\u064f \u064a\u064e\u062e\u0652\u062a\u0650\u0645\u064f \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u064e \u0641\u0650\u064a \u0643\u064f\u0644\u0651\u0650 \u062b\u064e\u0644\u064e\u0627\u062b\u064d\u060c \u0648\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f: \u0644\u064e\u0648\u0652 \u0623\u064e\u0631\u064e\u062f\u062a\u0651\u064f \u0623\u064e\u0646\u0651 \u0623\u064e\u062e\u0652\u062a\u0650\u0645\u064e\u0647\u064f \u0641\u0650\u064a \u0623\u064e\u0642\u064e\u0644\u0651\u064e \u0645\u0650\u0646\u0652 \u062b\u064e\u0644\u064e\u0627\u062b\u064d \u0644\u064e\u062e\u064e\u062a\u064e\u0645\u0652\u062a\u064f\u0647\u064f\u060c \u0648\u064e\u0644\u064e\u0643\u0650\u0646\u0652 \u0645\u064e\u0627 \u0645\u064e\u0631\u064e\u0631\u0652\u062a\u064f \u0628\u0650\u0622\u064a\u064e\u0629\u064d \u0642\u064e\u0637\u0651\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0641\u064e\u0643\u0651\u064e\u0631\u0652\u062a\u064f \u0641\u0650\u064a\u0647\u064e\u0627 \u0648\u064e\u0641\u0650\u064a \u0623\u064e\u064a\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0623\u064f\u0646\u0652\u0632\u0650\u0644\u064e\u062a\u0652\u060c \u0648\u064e\u0641\u0650\u064a \u0623\u064e\u064a\u0651\u064d \u0648\u064e\u0642\u0652\u062a\u064d\u060c \u0641\u064e\u0644\u0650\u0630\u064e\u0644\u0650\u0643\u064e \u0635\u0650\u0631\u0652\u062a\u064f \u0623\u064e\u062e\u0652\u062a\u0650\u0645\u064f \u062b\u064e\u0644\u064e\u0627\u062b\u064e\u0629\u064e \u0623\u064e\u064a\u0651\u064e\u0627\u0645\u064d","\u0627\u0644\u0625\u0645\u0627\u0645 \u0639\u0644\u064a \u0628\u0646 \u0645\u0648\u0633\u0649 \u0627\u0644\u0631\u0636\u0627 (\u0639\u0644\u064a\u0647\u0645\u0627 \u0627\u0644\u0633\u0644\u0627\u0645)","\u0628\u062d\u0627\u0631 \u0627\u0644\u0623\u0646\u0648\u0627\u0631\u060c \u062c \u0668\u0669\u060c \u0635 \u0662\u0660\u0664")
B.a1u=new A.c3("\u0643\u064e\u0627\u0646\u064e \u0623\u064e\u0645\u0650\u064a\u0631\u064f \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0639\u064e\u0644\u0650\u064a\u0651\u064f \u0628\u0652\u0646\u064f \u0623\u064e\u0628\u0650\u064a \u0637\u064e\u0627\u0644\u0650\u0628\u064d \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u064e\u0627 \u0627\u0644\u0633\u0651\u064e\u0644\u064e\u0627\u0645\u064f \u0625\u0650\u0630\u064e\u0627 \u062e\u064e\u062a\u064e\u0645\u064e \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u064e \u0642\u064e\u0627\u0644\u064e: \u0627\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0627\u0634\u0652\u0631\u064e\u062d\u0652 \u0628\u0650\u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u0650 \u0635\u064e\u062f\u0652\u0631\u0650\u064a\u060c \u0648\u064e\u0627\u0633\u0652\u062a\u064e\u0639\u0652\u0645\u0650\u0644\u0652 \u0628\u0650\u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u0650 \u0628\u064e\u062f\u064e\u0646\u0650\u064a\u060c \u0648\u064e\u0646\u064e\u0648\u0651\u0650\u0631\u0652 \u0628\u0650\u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u0650 \u0628\u064e\u0635\u064e\u0631\u0650\u064a\u060c \u0648\u064e\u0623\u064e\u0637\u0652\u0644\u0650\u0642\u0652 \u0628\u0650\u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u0650 \u0644\u0650\u0633\u064e\u0627\u0646\u0650\u064a\u060c \u0648\u064e\u0623\u064e\u0639\u0650\u0646\u0651\u0650\u064a \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0645\u064e\u0627 \u0623\u064e\u0628\u0652\u0642\u064e\u064a\u0652\u062a\u064e\u0646\u0650\u064a\u060c \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u062d\u064e\u0648\u0652\u0644\u064e \u0648\u064e\u0644\u064e\u0627 \u0642\u064f\u0648\u0651\u064e\u0629\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u0650\u0643\u064e","\u0627\u0644\u0625\u0645\u0627\u0645 \u0639\u0644\u064a (\u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645)","\u0628\u062d\u0627\u0631 \u0627\u0644\u0623\u0646\u0648\u0627\u0631 - \u0637\u0628\u0639\u0629 \u062f\u0627\u0631 \u0625\u062d\u064a\u0627\u0621 \u0627\u0644\u062a\u0631\u0627\u062b \u0627\u0644\u0639\u0631\u0628\u064a\u060c \u062c\u0668\u0669 \u060c \u0635 \u0662\u0660\u0669")
B.a1v=new A.c3("\u0645\u064e\u0627 \u0671\u062c\u0652\u062a\u064e\u0645\u064e\u0639\u064e \u0642\u064e\u0648\u0652\u0645\u064c \u0641\u0650\u064a \u0628\u064e\u064a\u0652\u062a\u064d \u0645\u0650\u0646\u0652 \u0628\u064f\u064a\u064f\u0648\u062a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u062a\u0652\u0644\u064f\u0648\u0646\u064e \u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u064a\u064e\u062a\u064e\u062f\u064e\u0627\u0631\u064e\u0633\u064f\u0648\u0646\u064e\u0647\u064f \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0646\u064e\u0632\u064e\u0644\u064e\u062a\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u064f \u0627\u0644\u0633\u0651\u064e\u0643\u0650\u064a\u0646\u064e\u0629\u064f\u060c \u0648\u064e\u063a\u064e\u0634\u0650\u064a\u064e\u062a\u0652\u0647\u064f\u0645\u064f \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0629\u064f\u060c \u0648\u064e\u062d\u064e\u0641\u0651\u064e\u062a\u0652\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u064f\u060c \u0648\u064e\u0630\u064e\u0643\u064e\u0631\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0641\u0650\u064a\u0645\u064e\u0646\u0652 \u0639\u0650\u0646\u0652\u062f\u064e\u0647\u064f","\u0627\u0644\u0646\u0628\u064a \u0627\u0644\u0623\u0639\u0638\u0645 (\u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0622\u0644\u0647 \u0648\u0633\u0644\u0645)","\u0645\u064a\u0632\u0627\u0646 \u0627\u0644\u062d\u0643\u0645\u0629\u060c \u062c \u0663\u060c \u0635 \u0662\u0665\u0662\u0662")
B.a1D=new A.c3("\u064a\u064f\u0642\u064e\u0627\u0644\u064f \u0644\u0650\u0635\u064e\u0627\u062d\u0650\u0628\u0650 \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u0650: \u0671\u0642\u0652\u0631\u064e\u0623\u0652 \u0648\u064e\u0671\u0631\u0652\u0642\u064e \u0648\u064e\u0631\u064e\u062a\u0651\u0650\u0644\u0652 \u0643\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u064e \u062a\u064f\u0631\u064e\u062a\u0651\u0650\u0644\u064f \u0641\u0650\u064a \u062f\u064e\u0627\u0631\u0650 \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627\u060c \u0641\u064e\u0625\u0650\u0646\u0651\u064e \u0645\u064e\u0646\u0652\u0632\u0650\u0644\u064e\u062a\u064e\u0643\u064e \u0639\u0650\u0646\u0652\u062f\u064e \u0622\u062e\u064e\u0631\u0650 \u0622\u064a\u064e\u0629\u064d \u0643\u064e\u0646\u0652\u062a\u064e \u062a\u064e\u0642\u0652\u0631\u064e\u0623\u064f\u0647\u064e\u0627","\u0627\u0644\u0646\u0628\u064a \u0627\u0644\u0623\u0639\u0638\u0645 (\u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0622\u0644\u0647 \u0648\u0633\u0644\u0645)","\u0645\u064a\u0632\u0627\u0646 \u0627\u0644\u062d\u0643\u0645\u0629\u060c \u062c \u0663\u060c \u0635 \u0662\u0665\u0662\u0661")
B.a1h=new A.c3("\u062e\u064e\u064a\u0652\u0631\u064f\u0643\u064f\u0645\u0652 \u0645\u064e\u0646\u0652 \u062a\u064e\u0639\u064e\u0644\u0651\u064e\u0645\u064e \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u064e \u0648\u064e\u0639\u064e\u0644\u0651\u064e\u0645\u064e\u0647\u064f","\u0627\u0644\u0646\u0628\u064a \u0627\u0644\u0623\u0639\u0638\u0645 (\u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0622\u0644\u0647 \u0648\u0633\u0644\u0645)","\u0645\u064a\u0632\u0627\u0646 \u0627\u0644\u062d\u0643\u0645\u0629\u060c \u062c \u0663\u060c \u0635 \u0662\u0665\u0662\u0661")
B.a1L=new A.c3("\u0625\u0650\u0646\u0652 \u0623\u064e\u0631\u064e\u062f\u062a\u0651\u064f\u0645 \u0639\u064e\u064a\u0652\u0634\u064e \u0627\u0644\u0633\u0651\u064f\u0639\u064e\u062f\u064e\u0627\u0621\u0650 \u0648\u064e\u0645\u064e\u0648\u062a\u064e \u0627\u0644\u0634\u0651\u064f\u0647\u064e\u062f\u064e\u0627\u0621\u0650 \u0648\u064e\u0627\u0644\u0646\u0651\u064e\u062c\u064e\u0627\u0629\u064e \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u062d\u064e\u0633\u0652\u0631\u064e\u0629\u0650 \u0648\u064e\u0627\u0644\u0638\u0651\u0650\u0644\u0651\u064e \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u062d\u064e\u0631\u064f\u0648\u0631\u0650 \u0648\u064e\u0627\u0644\u0652\u0647\u064f\u062f\u064e\u0649 \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0636\u0651\u064e\u0644\u064e\u0627\u0644\u064e\u0629\u0650\u060c \u0641\u064e\u0671\u062f\u0652\u0631\u064f\u0633\u064f\u0648\u0627 \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u064e\u060c \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0643\u064e\u0644\u064e\u0627\u0645\u064f \u0671\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0670\u0646\u0650 \u0648\u064e\u062d\u0650\u0631\u0652\u0632\u064c \u0645\u0650\u0646\u064e \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u0650 \u0648\u064e\u0631\u064f\u062c\u0652\u062d\u064e\u0627\u0646\u064c \u0641\u0650\u064a \u0627\u0644\u0652\u0645\u0650\u064a\u0632\u064e\u0627\u0646\u0650","\u0627\u0644\u0646\u0628\u064a \u0627\u0644\u0623\u0639\u0638\u0645 (\u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0622\u0644\u0647 \u0648\u0633\u0644\u0645)","\u0645\u064a\u0632\u0627\u0646 \u0627\u0644\u062d\u0643\u0645\u0629\u060c \u062c \u0663\u060c \u0635 \u0662\u0665\u0662\u0661")
B.a1J=new A.c3("\u0639\u064e\u0646\u0650 \u0627\u064e\u0644\u0632\u0651\u064f\u0647\u0652\u0631\u0650\u064a\u0651\u0650 \u0642\u064e\u0627\u0644\u064e: \u0642\u064f\u0644\u0652\u062a\u064f \u0644\u0650\u0639\u064e\u0644\u0650\u064a\u0651\u0650 \u0628\u0652\u0646\u0650 \u0627\u064e\u0644\u0652\u062d\u064f\u0633\u064e\u064a\u0652\u0646\u0650 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u064e\u0627 \u0627\u064e\u0644\u0633\u0651\u064e\u0644\u0627\u064e\u0645\u064f: \u0623\u064e\u064a\u0651\u064f \u0627\u064e\u0644\u0652\u0623\u064e\u0639\u0652\u0645\u064e\u0627\u0644\u0650 \u0623\u064e\u0641\u0652\u0636\u064e\u0644\u064f\u061f \u0642\u064e\u0627\u0644\u064e \u0627\u064e\u0644\u0652\u062d\u064e\u0627\u0644\u0651\u064f \u0627\u064e\u0644\u0652\u0645\u064f\u0631\u0652\u062a\u064e\u062d\u0650\u0644\u064f\u060c \u0642\u064f\u0644\u0652\u062a\u064f: \u0648\u064e\u0645\u064e\u0627 \u0627\u064e\u0644\u0652\u062d\u064e\u0627\u0644\u0651\u064f \u0627\u064e\u0644\u0652\u0645\u064f\u0631\u0652\u062a\u064e\u062d\u0650\u0644\u064f\u061f \u0642\u064e\u0627\u0644\u064e: \u0641\u064e\u062a\u0652\u062d\u064f \u0627\u064e\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u0650 \u0648\u064e\u062e\u064e\u062a\u0652\u0645\u064f\u0647\u064f\u060c \u0643\u064f\u0644\u0651\u064e\u0645\u064e\u0627 \u062d\u064e\u0644\u0651\u064e \u0628\u0650\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u0647\u0650 \u0671\u0631\u0652\u062a\u064e\u062d\u064e\u0644\u064e \u0641\u0650\u064a \u0622\u062e\u0650\u0631\u0650\u0647\u0650","\u0627\u0644\u0625\u0645\u0627\u0645 \u0639\u0644\u064a \u0628\u0646 \u0627\u0644\u062d\u0633\u064a\u0646 (\u0639\u0644\u064a\u0647\u0645\u0627 \u0627\u0644\u0633\u0644\u0627\u0645)","\u0628\u062d\u0627\u0631 \u0627\u0644\u0623\u0646\u0648\u0627\u0631\u060c \u062c \u0668\u0669\u060c \u0635 \u0662\u0660\u0664")
B.a1f=new A.c3("\u0639\u064e\u0646\u0652 \u0623\u064e\u0628\u0650\u064a \u0639\u064e\u0628\u0652\u062f\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0627\u0644\u0633\u0651\u064e\u0644\u064e\u0627\u0645\u064f \u0642\u064e\u0627\u0644\u064e: \u0642\u0650\u064a\u0644\u064e: \u064a\u064e\u0627 \u0631\u064e\u0633\u064f\u0648\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0623\u064e\u064a\u0651\u064f \u0627\u0644\u0631\u0651\u0650\u062c\u064e\u0627\u0644\u0650 \u062e\u064e\u064a\u0652\u0631\u064c\u061f \u0642\u064e\u0627\u0644\u064e: \u0627\u0644\u0652\u062d\u064e\u0627\u0644\u0651\u064f \u0627\u064e\u0644\u0652\u0645\u064f\u0631\u0652\u062a\u064e\u062d\u0650\u0644\u064f\u060c \u0642\u0650\u064a\u0644\u064e: \u064a\u064e\u0627 \u0631\u064e\u0633\u064f\u0648\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0645\u064e\u0627 \u0627\u0644\u0652\u062d\u064e\u0627\u0644\u0651\u064f \u0627\u064e\u0644\u0652\u0645\u064f\u0631\u0652\u062a\u064e\u062d\u0650\u0644\u064f\u061f \u0642\u064e\u0627\u0644\u064e: \u0627\u0644\u0652\u0641\u064e\u0627\u062a\u0650\u062d\u064f \u0627\u0644\u0652\u062e\u064e\u0627\u062a\u0650\u0645\u0652\u060c \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u064a\u064e\u0641\u0652\u062a\u064e\u062d\u064f \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u064e \u0648\u064e\u064a\u064e\u062e\u0652\u062a\u0650\u0645\u064f\u0647\u064f\u060c \u0641\u064e\u0644\u064e\u0647\u064f \u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062f\u064e\u0639\u0652\u0648\u064e\u0629\u064c \u0645\u064f\u0633\u0652\u062a\u064e\u062c\u064e\u0627\u0628\u064e\u0629\u064c","\u0627\u0644\u0646\u0628\u064a \u0627\u0644\u0623\u0639\u0638\u0645 (\u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0622\u0644\u0647 \u0648\u0633\u0644\u0645)","\u0628\u062d\u0627\u0631 \u0627\u0644\u0623\u0646\u0648\u0627\u0631\u060c \u062c \u0668\u0669\u060c \u0635 \u0662\u0660\u0665")
B.a1F=new A.c3("\u0648\u064e\u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u0628\u0650\u062a\u0650\u0644\u064e\u0627\u0648\u064e\u0629\u0650 \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u0650 \u0639\u064e\u0644\u064e\u0649 \u0643\u064f\u0644\u0651\u0650 \u062d\u064e\u0627\u0644\u064d","\u0627\u0644\u0646\u0628\u064a \u0627\u0644\u0623\u0639\u0638\u0645 (\u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0622\u0644\u0647 \u0648\u0633\u0644\u0645)","\u0648\u0633\u0627\u0626\u0644 \u0627\u0644\u0634\u064a\u0639\u0629\u060c \u062c \u0666\u060c \u0635 \u0661\u0668\u0666")
B.a1o=new A.c3("\u062a\u064e\u0639\u064e\u0644\u0651\u064e\u0645\u064f\u0648\u0627 \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u064e \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0623\u064e\u062d\u0652\u0633\u064e\u0646\u064f \u0627\u0644\u0652\u062d\u064e\u062f\u0650\u064a\u062b\u0650\u060c \u0648\u064e\u062a\u064e\u0641\u064e\u0642\u0651\u064e\u0647\u064f\u0648\u0627 \u0641\u0650\u064a\u0650\u0647 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0631\u064e\u0628\u0650\u064a\u0639\u064f \u0627\u0644\u0652\u0642\u064f\u0644\u064f\u0648\u0628\u0650\u060c \u0648\u064e\u0671\u0633\u0652\u062a\u064e\u0634\u0652\u0641\u064f\u0648\u0627 \u0628\u0650\u0646\u064f\u0648\u0631\u0650\u0647\u0650 \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0634\u0650\u0641\u064e\u0627\u0621\u064f \u0627\u0644\u0635\u0651\u064f\u062f\u064f\u0648\u0631\u0650\u060c \u0648\u064e\u0623\u064e\u062d\u0652\u0633\u0650\u0646\u064f\u0648\u0627 \u062a\u0650\u0644\u064e\u0627\u0648\u064e\u062a\u064e\u0647\u064f \u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0623\u064e\u0646\u0652\u0641\u064e\u0639\u064f \u0627\u0644\u0652\u0642\u064e\u0635\u064e\u0635\u0650","\u0627\u0644\u0625\u0645\u0627\u0645 \u0639\u0644\u064a (\u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645)","\u0645\u064a\u0632\u0627\u0646 \u0627\u0644\u062d\u0643\u0645\u0629\u060c \u062c \u0663\u060c \u0635 \u0662\u0665\u0662\u0661")
B.a1G=new A.c3("\u0625\u0650\u0646\u0651\u064e \u0644\u0650\u0644\u0652\u0642\u064f\u0644\u064f\u0648\u0628\u0650 \u0635\u064e\u062f\u064e\u0623\u064c \u0643\u064e\u0635\u064e\u062f\u064e\u0625\u0650 \u0627\u0644\u0646\u0651\u064f\u062d\u064e\u0627\u0633\u0650\u060c \u0641\u064e\u0671\u062c\u0652\u0644\u064f\u0648\u0647\u064e\u0627 \u0628\u0650\u0627\u0644\u0650\u0627\u0633\u0652\u062a\u0650\u063a\u0652\u0641\u064e\u0627\u0631\u0650 \u0648\u064e\u062a\u0650\u0644\u064e\u0627\u0648\u064e\u0629\u0650 \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u0650","\u0627\u0644\u0646\u0628\u064a \u0627\u0644\u0623\u0639\u0638\u0645 (\u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0622\u0644\u0647 \u0648\u0633\u0644\u0645)","\u0628\u062d\u0627\u0631 \u0627\u0644\u0623\u0646\u0648\u0627\u0631\u060c \u062c \u0667\u0664\u060c \u0635 \u0661\u0667\u0662")
B.a1i=new A.c3("\u0645\u064e\u0646\u0652 \u0642\u064e\u0631\u064e\u0623\u064e \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u064e \u0643\u064e\u0627\u0646\u064e\u062a\u0652 \u0644\u064e\u0647\u064f \u062f\u064e\u0639\u0652\u0648\u064e\u0629\u064c \u0645\u064f\u062c\u064e\u0627\u0628\u064e\u0629\u064c\u060c \u0625\u0650\u0645\u0651\u064e\u0627 \u0645\u064f\u0639\u064e\u062c\u0651\u064e\u0644\u064e\u0629\u064c \u0648\u064e\u0625\u0650\u0645\u0651\u064e\u0627 \u0645\u064f\u0624\u064e\u062c\u0651\u064e\u0644\u064e\u0629\u064c","\u0627\u0644\u0625\u0645\u0627\u0645 \u0627\u0644\u062d\u0633\u0646 \u0628\u0646 \u0639\u0644\u064a (\u0639\u0644\u064a\u0647\u0645\u0627 \u0627\u0644\u0633\u0644\u0627\u0645)","\u0628\u062d\u0627\u0631 \u0627\u0644\u0623\u0646\u0648\u0627\u0631\u060c \u062c \u0669\u0660\u060c \u0635 \u0663\u0661\u0663")
B.a1B=new A.c3("\u0627\u0644\u0652\u062d\u064e\u0627\u0641\u0650\u0638\u064f \u0644\u0650\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u0650 \u0627\u0644\u0652\u0639\u064e\u0627\u0645\u0650\u0644\u064f \u0628\u0650\u0647\u0650\u060c \u0645\u064e\u0639\u064e \u0627\u0644\u0633\u0651\u064e\u0641\u064e\u0631\u064e\u0629\u0650 \u0627\u0644\u0652\u0643\u0650\u0631\u064e\u0627\u0645\u0650 \u0627\u0644\u0652\u0628\u064e\u0631\u064e\u0631\u064e\u0629\u0650","\u0627\u0644\u0625\u0645\u0627\u0645 \u062c\u0639\u0641\u0631 \u0627\u0644\u0635\u0627\u062f\u0642 (\u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645)","\u0627\u0644\u0643\u0627\u0641\u064a\u060c \u062c \u0662\u060c \u0635 \u0666\u0660\u0663")
B.a1P=new A.c3("\u0644\u064e\u064a\u0652\u0633\u064e \u0634\u064e\u064a\u0652\u0621\u064c \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0634\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u0650 \u0623\u064e\u0634\u064e\u062f\u0651\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0642\u0650\u0631\u064e\u0627\u0621\u064e\u0629\u0650 \u0641\u0650\u064a \u0627\u0644\u0652\u0645\u064f\u0635\u0652\u062d\u064e\u0641\u0650 \u0646\u064e\u0638\u064e\u0631\u064b\u0627\u060c \u0648\u064e\u0627\u0644\u0652\u0645\u064f\u0635\u0652\u062d\u064e\u0641\u064f \u0641\u0650\u064a \u0627\u0644\u0652\u0628\u064e\u064a\u0652\u062a\u0650 \u064a\u064e\u0637\u0652\u0631\u064f\u062f\u064f \u0627\u0644\u0652\u0634\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u064e","\u0627\u0644\u0646\u0628\u064a \u0627\u0644\u0623\u0639\u0638\u0645 (\u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0622\u0644\u0647 \u0648\u0633\u0644\u0645)","\u0628\u062d\u0627\u0631 \u0627\u0644\u0623\u0646\u0648\u0627\u0631\u060c \u062c \u0668\u0669\u060c \u0635 \u0662\u0660\u0661")
B.a1R=new A.c3("\u0639\u064e\u0646\u0652 \u0625\u0650\u0633\u0652\u062d\u064e\u0627\u0642\u064e \u0628\u0652\u0646\u0650 \u0639\u064e\u0645\u0651\u064e\u0627\u0631\u064d\u060c \u0639\u064e\u0646\u0652 \u0623\u064e\u0628\u0650\u064a \u0639\u064e\u0628\u0652\u062f\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 (\u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0627\u0644\u0633\u0651\u064e\u0644\u064e\u0627\u0645\u064f) \u0642\u064e\u0627\u0644\u064e: \u0642\u064f\u0644\u0652\u062a\u064f \u0644\u064e\u0647\u064f: \u062c\u064f\u0639\u0650\u0644\u0652\u062a\u064f \u0641\u0650\u062f\u064e\u0627\u0643\u064e \u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064e\u062d\u0652\u0641\u064e\u0638\u064f \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u064e \u0639\u064e\u0644\u064e\u0649 \u0638\u064e\u0647\u0652\u0631\u0650 \u0642\u064e\u0644\u0652\u0628\u0650\u064a \u0641\u064e\u0623\u064e\u0642\u0652\u0631\u064e\u0624\u064f\u0647\u064f \u0639\u064e\u0644\u064e\u0649 \u0638\u064e\u0647\u0652\u0631\u0650 \u0642\u064e\u0644\u0652\u0628\u0650\u064a \u0623\u064e\u0641\u0652\u0636\u064e\u0644\u064f \u0623\u064e\u0648\u0652 \u0623\u064e\u0646\u0652\u0638\u064f\u0631\u064f \u0641\u0650\u064a \u0627\u0644\u0652\u0645\u064f\u0635\u0652\u062d\u064e\u0641\u0650\u061f \u0642\u064e\u0627\u0644\u064e: \u0641\u0642\u064e\u0627\u0644\u064e \u0644\u0650\u064a: (\u0628\u064e\u0644\u0650 \u0627\u0642\u0652\u0631\u064e\u0623\u0652\u0647\u064f \u0648\u064e\u0627\u0646\u0652\u0638\u064f\u0631\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u0645\u064f\u0635\u0652\u062d\u064e\u0641\u0650 \u0641\u064e\u0647\u064f\u0648\u064e \u0623\u064e\u0641\u0652\u0636\u064e\u0644\u064f\u060c \u0623\u064e\u0645\u064e\u0627 \u0639\u064e\u0644\u0650\u0645\u0652\u062a\u064e \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0646\u0651\u064e\u0638\u064e\u0631\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0645\u064f\u0635\u0652\u062d\u064e\u0641\u0650 \u0639\u0650\u0628\u064e\u0627\u062f\u064e\u0629\u064c)","\u0627\u0644\u0625\u0645\u0627\u0645 \u062c\u0639\u0641\u0631 \u0627\u0644\u0635\u0627\u062f\u0642 (\u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645)",u.G)
B.a1O=new A.c3("\u0639\u064e\u0646\u0652 \u0639\u064e\u0628\u0652\u062f\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0628\u0652\u0646\u0650 \u0633\u064f\u0644\u064e\u064a\u0652\u0645\u064e\u0627\u0646\u064e\u060c \u0642\u064e\u0627\u0644\u064e: \u0633\u064e\u0623\u064e\u0644\u0652\u062a\u064f \u0623\u064e\u0628\u064e\u0627 \u0639\u064e\u0628\u0652\u062f\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 (\u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0627\u0644\u0633\u0651\u064e\u0644\u064e\u0627\u0645\u064f) \u0639\u064e\u0646\u0652 \u0642\u064e\u0652\u0648\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0632\u0651\u064e \u0648\u064e\u062c\u064e\u0644\u0651\u064e: (\u0648\u064e\u0631\u064e\u062a\u0651\u0650\u0644\u0650 \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u064e \u062a\u064e\u0631\u0652\u062a\u0650\u064a\u0644\u064b\u0627) \u0642\u064e\u0627\u0644\u064e: (\u0642\u064e\u0627\u0644\u064e \u0623\u064e\u0645\u0650\u064a\u0631\u064f \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0635\u064e\u0644\u064e\u0648\u064e\u0627\u062a\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650: \u0628\u064e\u064a\u0651\u0650\u0646\u0652\u0647\u064f \u062a\u0650\u0628\u0652\u064a\u064e\u0627\u0646\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0647\u064f\u0630\u0651\u064e\u0647\u064f \u0647\u064e\u0630\u0651\u064e \u0627\u0644\u0634\u0651\u0650\u0639\u0652\u0631\u0650\u060c \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0646\u0652\u062b\u064f\u0631\u0652\u0647\u064f \u0646\u064e\u062b\u0652\u0631\u064e \u0627\u0644\u0631\u0651\u064e\u0645\u0652\u0644\u0650\u060c \u0648\u064e\u0644\u064e\u0643\u0650\u0646\u0652 \u0623\u064e\u0641\u0652\u0632\u0650\u0639\u064f\u0648\u0627 \u0642\u064f\u0644\u064f\u0648\u0628\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0652\u0642\u064e\u0627\u0633\u0650\u064a\u064e\u0629\u064e\u060c \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0643\u064f\u0646\u0652 \u0647\u064e\u0645\u0651\u064f \u0623\u064e\u062d\u064e\u062f\u0650\u0643\u064f\u0645\u0652 \u0622\u062e\u0650\u0631\u064e \u0627\u0644\u0633\u0651\u064f\u0648\u0631\u064e\u0629\u0650)","\u0627\u0644\u0625\u0645\u0627\u0645 \u062c\u0639\u0641\u0631 \u0627\u0644\u0635\u0627\u062f\u0642 (\u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645)","\u0634\u0631\u062d \u0623\u0635\u0648\u0644 \u0627\u0644\u0643\u0627\u0641\u064a (\u0644\u0644\u0645\u0627\u0632\u0646\u062f\u0631\u0627\u0646\u064a)\u060c \u062c \u0661\u0661\u060c \u0635 \u0664\u0664")
B.a1p=new A.c3("\u062b\u064e\u0644\u064e\u0627\u062b\u064e\u0629\u064c \u064a\u064e\u0634\u0652\u0643\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0639\u064e\u0632\u0651\u064e \u0648\u064e\u062c\u064e\u0644\u0651\u064e: \u0645\u064e\u0633\u0652\u062c\u0650\u062f\u064c \u062e\u064e\u0631\u064e\u0627\u0628\u064c \u0644\u064e\u0627 \u064a\u064f\u0635\u064e\u0644\u0651\u0650\u064a \u0641\u0650\u064a\u0647\u0650 \u0623\u064e\u0647\u0652\u0644\u064f\u0647\u064f\u060c \u0648\u064e\u0639\u064e\u0627\u0644\u0650\u0645\u064c \u0628\u064e\u064a\u0652\u0646\u064e \u062c\u064f\u0647\u0651\u064e\u0627\u0644\u064d\u060c \u0648\u064e\u0645\u064f\u0635\u0652\u062d\u064e\u0641\u064c \u0645\u064f\u0639\u064e\u0644\u0651\u064e\u0642\u064c \u0642\u064e\u062f\u0652 \u0648\u064e\u0642\u064e\u0639\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0627\u0644\u0652\u063a\u064f\u0628\u064e\u0627\u0631\u064f \u0644\u064e\u0627 \u064a\u064f\u0642\u0652\u0631\u064e\u0623\u064f \u0641\u0650\u064a\u0647\u0650","\u0627\u0644\u0625\u0645\u0627\u0645 \u062c\u0639\u0641\u0631 \u0627\u0644\u0635\u0627\u062f\u0642 (\u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645)",u.G)
B.a1z=new A.c3("\u0645\u064e\u0646\u0652 \u0642\u064e\u0631\u064e\u0623\u064e \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0645\u064f\u0635\u0652\u062d\u064e\u0641\u0650 \u0645\u064f\u062a\u0651\u0650\u0639\u064e \u0628\u0650\u0628\u064e\u0635\u064e\u0631\u0650\u0647\u0650\u060c \u0648\u064e\u062e\u064f\u0641\u0651\u0650\u0641\u064e \u0639\u064e\u0646\u0652 \u0648\u064e\u0627\u0644\u0650\u062f\u064e\u064a\u0652\u0647\u0650 \u0648\u064e\u0625\u0650\u0646\u0652 \u0643\u064e\u0627\u0646\u064e\u0627 \u0643\u064e\u0627\u0641\u0650\u0631\u064e\u064a\u0652\u0646\u0650","\u0627\u0644\u0625\u0645\u0627\u0645 \u062c\u0639\u0641\u0631 \u0627\u0644\u0635\u0627\u062f\u0642 (\u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645)",u.G)
B.a1H=new A.c3("\u0645\u064e\u0646\u0652 \u0642\u064e\u0631\u064e\u0623\u064e \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u064e \u0642\u064e\u0627\u0626\u0650\u0645\u064b\u0627 \u0641\u0650\u064a \u0635\u064e\u0644\u064e\u0627\u062a\u0650\u0647\u0650 \u0643\u064e\u062a\u064e\u0628\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0647\u064f \u0628\u0650\u0643\u064f\u0644\u0650 \u062d\u064e\u0631\u0652\u0641\u064d \u0645\u0650\u0627\u0626\u064e\u0629\u064e \u062d\u064e\u0633\u064e\u0646\u064e\u0629\u064d\u060c \u0648\u064e\u0645\u064e\u0646\u0652 \u0642\u064e\u0631\u064e\u0623\u064e \u0641\u0650\u064a \u0635\u064e\u0644\u064e\u0627\u062a\u0650\u0647\u0650 \u062c\u064e\u0627\u0644\u0650\u0633\u064b\u0627 \u0643\u064e\u062a\u064e\u0628\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0647\u064f \u0628\u0650\u0643\u064f\u0644\u0650 \u062d\u064e\u0631\u0652\u0641\u064d \u062e\u064e\u0645\u0652\u0633\u0650\u064a\u0646\u064e \u062d\u064e\u0633\u064e\u0646\u064e\u0629\u064d\u060c \u0648\u064e\u0645\u064e\u0646\u0652 \u0642\u064e\u0631\u064e\u0623\u064e \u0641\u0650\u064a \u063a\u064e\u064a\u0652\u0631\u0650 \u0635\u064e\u0644\u064e\u0627\u062a\u0650\u0647\u0650 \u0643\u064e\u062a\u064e\u0628\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0647\u064f \u0628\u0650\u0643\u064f\u0644\u0650 \u062d\u064e\u0631\u0652\u0641\u064d \u0639\u064e\u0634\u0652\u0631\u064e \u062d\u064e\u0633\u064e\u0646\u064e\u0627\u062a\u064d","\u0627\u0644\u0625\u0645\u0627\u0645 \u0645\u062d\u0645\u062f \u0627\u0644\u0628\u0627\u0642\u0631 (\u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645)","\u0628\u062d\u0627\u0631 \u0627\u0644\u0623\u0646\u0648\u0627\u0631\u060c \u062c \u0668\u0669\u060c \u0635 \u0662\u0660\u0660")
