B.aW8=new A.w("\u0645\u0646 \u0623\u0645\u062b\u0644\u0629 \u0627\u0644\u0645\u062f \u0627\u0644\u0645\u0646\u0641\u0635\u0644 \u0627\u0644\u062c\u0627\u0626\u0632",B.agf,"\u0642\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0643\u064f\u0645\u06e1","\u0627\u0644\u0645\u062f \u0627\u0644\u0645\u0646\u0641\u0635\u0644 \u0627\u0644\u062c\u0627\u0626\u0632 \u064a\u0643\u0648\u0646 \u0639\u0646\u062f\u0645\u0627 \u064a\u0623\u062a\u064a \u0628\u0639\u062f \u062d\u0631\u0641 \u0627\u0644\u0645\u062f \u0647\u0645\u0632\u0629 \u0645\u0646\u0641\u0635\u0644\u0629 \u0641\u064a \u0643\u0644\u0645\u0629 \u0623\u062e\u0631\u0649 \u0645\u062b\u0644 ( \u0642\u064f\u0648\u0653\u0627\u0652 \u0623\u064e\u0646\u0641\u064f\u0633\u064e\u0643\u064f\u0645\u06e1 ) \u0641\u0642\u062f \u0623\u062a\u062a \u0647\u0645\u0632\u0629 \u0645\u0646\u0641\u0635\u0644\u0629 \u0628\u0639\u062f \u062d\u0631\u0641 \u0627\u0644\u0645\u062f ( \u0627\u0644\u0648\u0627\u0648 )\u060c \u0623\u0645\u0627 \u0641\u064a \u0643\u0644\u0645\u0629 ( \u0671\u0644\u0633\u0651\u064e\u0627\u0653\u0626\u0650\u0644\u064e ) \u0641\u0627\u0644\u0647\u0645\u0632\u0629 \u0641\u064a \u0646\u0641\u0633 \u0627\u0644\u0643\u0644\u0645\u0629 \u0645\u0639 \u062d\u0631\u0641 \u0627\u0644\u0645\u062f \u0648\u0641\u064a \u0643\u0644\u0645\u0629 ( \u0671\u0644\u0636\u0651\u064e\u0627\u0653\u0644\u0651\u0650\u064a\u0646\u064e ) \u0644\u0627 \u064a\u0648\u062c\u062f \u0647\u0645\u0632\u0629 \u0628\u0639\u062f \u062d\u0631\u0641 \u0627\u0644\u0645\u062f")
B.b0P=new A.w("\u0645\u0642\u062f\u0627\u0631 \u0645\u062f \u0627\u0644\u0645\u062f \u0627\u0644\u0645\u0646\u0641\u0635\u0644 \u0627\u0644\u062c\u0627\u0626\u0632 \u0647\u0648",B.Cy,"\u0664 \u0623\u0648 \u0665 \u062d\u0631\u0643\u0627\u062a","\u0645\u0642\u062f\u0627\u0631\u0647 \u0645\u062f\u0647 \u0643\u0627\u0644\u0645\u062f \u0627\u0644\u0645\u062a\u0635\u0644 \u0627\u0644\u0648\u0627\u062c\u0628 \u0664 \u0623\u0648 \u0665 \u062d\u0631\u0643\u0627\u062a \u0644\u062d\u0641\u0635 \u0639\u0646 \u0639\u0627\u0635\u0645 \u0645\u0646 \u0637\u0631\u064a\u0642 \u0627\u0644\u0634\u0627\u0637\u0628\u064a\u0629 \u060c \u0648\u064a\u064f\u0645\u062f \u0639\u0646\u062f \u0627\u0644\u0648\u0635\u0644 \u0641\u0642\u0637 \u0644\u0623\u0646\u0647 \u0639\u0646\u062f \u0627\u0644\u0648\u0642\u0641 \u064a\u0646\u062a\u0641\u064a \u0633\u0628\u0628 \u0627\u0644\u0645\u062f \u0648\u0647\u0648 \u0627\u0644\u0647\u0645\u0632\u0629 \u0627\u0644\u0645\u0646\u0641\u0635\u0644\u0629\u060c \u0648\u062c\u0627\u0632 \u0645\u062f\u0647 \u0628\u0645\u0642\u062f\u0627\u0631 \u062d\u0631\u0643\u062a\u064a\u0646 \u0644\u062d\u0641\u0635 \u0639\u0646 \u0639\u0627\u0635\u0645 \u0645\u0646 \u0637\u0631\u064a\u0642 \u0637\u064a\u0628\u0629 \u0627\u0644\u0646\u0634\u0631")
B.b1c=new A.w("\u064a\u062b\u0628\u062a \u0627\u0644\u0645\u062f \u0627\u0644\u0645\u0646\u0641\u0635\u0644 \u0627\u0644\u062c\u0627\u0626\u0632 \u0639\u0646\u062f \u0627\u0644\u0648\u0635\u0644 \u0648\u0639\u0646\u062f \u0627\u0644\u0648\u0642\u0641",B.S,"\u062e\u0637\u0623","\u064a\u064f\u0645\u062f \u0639\u0646\u062f \u0627\u0644\u0648\u0635\u0644 \u0641\u0642\u0637\u060c \u0644\u0623\u0646\u0647 \u0639\u0646\u062f \u0627\u0644\u0648\u0642\u0641 \u064a\u0646\u062a\u0641\u064a \u0633\u0628\u0628 \u0627\u0644\u0645\u062f \u0648\u0647\u0648 \u0627\u0644\u0647\u0645\u0632\u0629 \u0627\u0644\u0645\u0646\u0641\u0635\u0644\u0629\u060c \u0641\u0645\u062b\u0644\u064b\u0627 \u0639\u0646\u062f \u0627\u0644\u0648\u0642\u0641 \u0639\u0644\u0649 \u0643\u0644\u0645\u0629 ( \u0671\u0644\u0631\u0651\u064f\u062c\u06e1\u0639\u064e\u0649\u0670\u0653 ) \u0645\u0646 \u0642\u0648\u0644\u0647 \u062a\u0639\u0627\u0644\u0649: { \u0625\u0650\u0646\u0651\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0671\u0644\u0631\u0651\u064f\u062c\u06e1\u0639\u064e\u0649\u0670\u0653 (\u0668) \u0623\u064e\u0631\u064e\u0621\u064e\u064a\u06e1\u062a\u064e } \u064a\u0643\u0648\u0646 \u0627\u0644\u0645\u062f \u0641\u064a \u0646\u0647\u0627\u064a\u0629 \u0627\u0644\u0643\u0644\u0645\u0629 \u0637\u0628\u064a\u0639\u064a\u064b\u0627 \u064a\u064f\u0645\u062f \u0628\u0645\u0642\u062f\u0627\u0631 \u062d\u0631\u0643\u062a\u064a\u0646 \u0641\u0642\u0637\u060c \u0623\u0645\u0627 \u0639\u0646\u062f \u0627\u0644\u0648\u0635\u0644 \u0641\u064a\u0643\u0648\u0646 \u0645\u062f\u064b\u0627 \u0645\u0646\u0641\u0635\u0644\u064b\u0627 \u062c\u0627\u0626\u0632\u064b\u0627")
B.ahn=A.a(s(["\u0644\u0627\u062e\u062a\u0644\u0627\u0641 \u0627\u0644\u0642\u0631\u0627\u0621 \u0641\u064a\u0647","\u0644\u0627\u062a\u0641\u0627\u0642 \u0627\u0644\u0642\u0631\u0627\u0621 \u0639\u0644\u0649 \u0645\u062f\u0651\u0647"]),t.s)
B.aW0=new A.w("\u0644\u0645\u0627\u0630\u0627 \u0633\u064f\u0645\u0651\u064a\u064e \u0627\u0644\u0645\u062f \u0627\u0644\u0645\u0646\u0641\u0635\u0644 \u0628\u0627\u0644\u062c\u0627\u0626\u0632",B.ahn,"\u0644\u0627\u062e\u062a\u0644\u0627\u0641 \u0627\u0644\u0642\u0631\u0627\u0621 \u0641\u064a\u0647","\u0633\u064f\u0645\u0651\u064a\u064e \u0628\u0627\u0644\u062c\u0627\u0626\u0632 \u0644\u0627\u062e\u062a\u0644\u0627\u0641 \u0627\u0644\u0642\u0631\u0627\u0621 \u0641\u064a\u0647\u060c \u0641\u0645\u0646\u0647\u0645 \u0645\u0646 \u0645\u062f\u0647 \u062d\u0631\u0643\u062a\u064a\u0646 \u0648\u0645\u0646\u0647\u0645 \u0645\u0646 \u0645\u062f\u0647 \u0623\u0643\u062b\u0631 \u0645\u0646 \u0630\u0644\u0643\u060c \u0623\u0645\u0627 \u0644\u062d\u0641\u0635 \u0645\u0646 \u0637\u0631\u064a\u0642 \u0627\u0644\u0634\u0627\u0637\u0628\u064a\u0629 \u0641\u0625\u0646\u0647 \u064a\u064f\u0645\u062f \u0628\u0645\u0642\u062f\u0627\u0631 \u0664 \u0623\u0648 \u0665 \u062d\u0631\u0643\u0627\u062a")
B.aak=A.a(s(["\u0644\u0627\u0646\u0641\u0635\u0627\u0644 \u0627\u0644\u0647\u0645\u0632\u0629 \u0639\u0646 \u062d\u0631\u0641 \u0627\u0644\u0645\u062f","\u0644\u0627\u062e\u062a\u0644\u0627\u0641 \u0627\u0644\u0642\u0631\u0627\u0621 \u0641\u064a\u0647"]),t.s)
B.b01=new A.w("\u0644\u0645\u0627\u0630\u0627 \u0633\u064f\u0645\u0651\u064a\u064e \u0627\u0644\u0645\u062f \u0627\u0644\u0645\u0646\u0641\u0635\u0644 \u0627\u0644\u062c\u0627\u0626\u0632 \u0628\u0627\u0644\u0645\u0646\u0641\u0635\u0644",B.aak,"\u0644\u0627\u0646\u0641\u0635\u0627\u0644 \u0627\u0644\u0647\u0645\u0632\u0629 \u0639\u0646 \u062d\u0631\u0641 \u0627\u0644\u0645\u062f","\u0633\u064f\u0645\u0651\u064a\u064e \u0628\u0627\u0644\u0645\u0646\u0641\u0635\u0644 \u0644\u0627\u0646\u0641\u0635\u0627\u0644 \u0627\u0644\u0647\u0645\u0632\u0629 \u0639\u0646 \u062d\u0631\u0641 \u0627\u0644\u0645\u062f\u060c \u0641\u062d\u0631\u0641 \u0627\u0644\u0645\u062f \u064a\u0643\u0648\u0646 \u0641\u064a \u0646\u0647\u0627\u064a\u0629 \u0643\u0644\u0645\u0629 \u0648\u0627\u0644\u0647\u0645\u0632\u0629 \u062a\u0643\u0648\u0646 \u0641\u064a \u0628\u062f\u0627\u064a\u0629 \u0627\u0644\u0643\u0644\u0645\u0629 \u0627\u0644\u062a\u064a \u0628\u0639\u062f\u0647\u0627")
B.a57=A.a(s(["\u0625\u0650\u0646\u0651\u064e\u0627\u0653 \u0623\u064e\u0639\u06e1\u0637\u064e\u064a\u06e1\u0646\u064e\u0670\u0643\u064e","\u062d\u064f\u0646\u064e\u0641\u064e\u0627\u0653\u0621\u064e","\u0623\u064f\u0648\u0652\u0644\u064e\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u06e1"]),t.s)
B.b_3=new A.w("\u0645\u0646 \u0623\u0645\u062b\u0644\u0629 \u0627\u0644\u0645\u062f \u0627\u0644\u0645\u0646\u0641\u0635\u0644 \u0627\u0644\u062c\u0627\u0626\u0632",B.a57,"\u0625\u0650\u0646\u0651\u064e\u0627\u0653 \u0623\u064e\u0639\u06e1\u0637\u064e\u064a\u06e1\u0646\u064e\u0670\u0643\u064e","\u0627\u0644\u0645\u062f \u0627\u0644\u0645\u0646\u0641\u0635\u0644 \u0627\u0644\u062c\u0627\u0626\u0632 \u064a\u0643\u0648\u0646 \u0639\u0646\u062f\u0645\u0627 \u064a\u0623\u062a\u064a \u0628\u0639\u062f \u062d\u0631\u0641 \u0627\u0644\u0645\u062f \u0647\u0645\u0632\u0629 \u0645\u0646\u0641\u0635\u0644\u0629 \u0641\u064a \u0643\u0644\u0645\u0629 \u0623\u062e\u0631\u0649 \u0645\u062b\u0644 ( \u0625\u0650\u0646\u0651\u064e\u0627\u0653 \u0623\u064e\u0639\u06e1\u0637\u064e\u064a\u06e1\u0646\u064e\u0670\u0643\u064e ) \u0641\u0642\u062f \u0623\u062a\u062a \u0647\u0645\u0632\u0629 \u0645\u0646\u0641\u0635\u0644\u0629 \u0628\u0639\u062f \u062d\u0631\u0641 \u0627\u0644\u0645\u062f ( \u0627\u0644\u0623\u0644\u0641 )\u060c \u0623\u0645\u0627 \u0641\u064a ( \u062d\u064f\u0646\u064e\u0641\u064e\u0627\u0653\u0621\u064e - \u0623\u064f\u0648\u0652\u0644\u064e\u0670\u0653\u0626\u0650\u0643\u064e ) \u0641\u0627\u0644\u0647\u0645\u0632\u0629 \u0641\u064a \u0646\u0641\u0633 \u0627\u0644\u0643\u0644\u0645\u0629 \u0645\u0639 \u062d\u0631\u0641 \u0627\u0644\u0645\u062f")
B.af8=A.a(s(["\u0645\u064e\u0627\u0644\u064f\u0647\u064f\u06e5\u0653 \u0625\u0650\u0630\u064e\u0627","\u0625\u0650\u0644\u0651\u064e\u0627 \u0671\u0628\u06e1\u062a\u0650\u063a\u064e\u0627\u0653\u0621\u064e","\u0671\u0644\u06e1\u0623\u064e\u0631\u064e\u0627\u0653\u0626\u0650\u0643\u0650"]),t.s)
B.b0z=new A.w("\u0645\u0646 \u0623\u0645\u062b\u0644\u0629 \u0627\u0644\u0645\u062f \u0627\u0644\u0645\u0646\u0641\u0635\u0644 \u0627\u0644\u062c\u0627\u0626\u0632",B.af8,"\u0645\u064e\u0627\u0644\u064f\u0647\u064f\u06e5\u0653 \u0625\u0650\u0630\u064e\u0627","\u0627\u0644\u0645\u062f \u0641\u064a \u0642\u0648\u0644\u0647 \u062a\u0639\u0627\u0644\u0649: ( \u0645\u064e\u0627\u0644\u064f\u0647\u064f\u06e5\u0653 \u0625\u0650\u0630\u064e\u0627 ) \u0647\u0648 \u0645\u062f \u0635\u0644\u0629 \u0643\u0628\u0631\u0649 \u0648\u064a\u064f\u0644\u062d\u064e\u0642 \u0628\u0627\u0644\u0645\u062f \u0627\u0644\u0645\u0646\u0641\u0635\u0644 \u0627\u0644\u062c\u0627\u0626\u0632 \u0641\u064a \u0627\u0644\u062d\u0643\u0645\u060c \u0641\u0642\u062f \u0623\u062a\u062a \u0647\u0645\u0632\u0629 \u0645\u0646\u0641\u0635\u0644\u0629 \u0628\u0639\u062f \u062d\u0631\u0641 \u0627\u0644\u0645\u062f ( \u0627\u0644\u0648\u0627\u0648 \u0627\u0644\u0645\u062f\u064a\u0629 \u0627\u0644\u0635\u063a\u064a\u0631\u0629 )")
